2026	Status CollectionImpl::acquire_file_lock(bool create) {
2027	  std::string lock_file_path = ailego::FileHelper::PathJoin(path_, "LOCK");
2028	
2029	  if (create) {
2030	    if (!lock_file_.create(lock_file_path.c_str(), 0)) {
2031	      return Status::InternalError("Can't create lock file: ", lock_file_path);
2032	    }
2033	  } else {
2034	    if (!lock_file_.open(lock_file_path.c_str(), options_.read_only_)) {
2035	      return Status::InternalError("Can't open lock file: ", lock_file_path);
2036	    }
2037	  }
2038	
2039	  if (options_.read_only_) {
2040	    if (!ailego::FileLock::TryLockShared(lock_file_.native_handle())) {
2041	      return Status::InternalError("Can't lock read-only collection: ",
2042	                                   lock_file_path);
2043	    }
2044	  } else {
2045	    if (!ailego::FileLock::TryLock(lock_file_.native_handle())) {
2046	      return Status::InternalError("Can't lock read-write collection: ",
2047	                                   lock_file_path);
2048	    }
2049	  }
2050	
2051	  return Status::OK();
2052	}
